verification.testSuite:
const { registerWildcard } = require('./router.js');
const mockApp = {
    get: (route, handler) => {
        if (route === '/*') {
            throw new TypeError('TypeError: Missing parameter name at 1: /*');
        }
        if (route === '/{*splat}') {
            return 'OK';
        }
        throw new Error('Unexpected route: ' + route);
    }
};
const res = registerWildcard(mockApp);
if (res !== 'OK') process.exit(1);
console.log('VERIFICATION_SUCCESS_STAGE_3');
process.exit(0);

